window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[121]={"id":"121","numero":121,"titre":"Handicap psychique","objectifs":[{"id":"121-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition du handicap psychique, connaître la différence avec le handicap intellectuel","contenu":"<p>On estime à <span class=\"kw-chiffre\">700 000</span> le nombre de personnes présentant un <span class=\"kw-def\">handicap psychique</span> en France. Le handicap psychique fait partie des <strong>1<sup>ères</sup> causes de handicap</strong> selon l'<span class=\"kw-def\">OMS</span>.</p>\n      <p>Le <span class=\"kw-def\">handicap psychique</span> est <strong>secondaire à un trouble psychiatrique</strong>. Il est en lien avec un ensemble de déficiences :</p>\n      <ul>\n        <li><strong>Déficits cognitifs spécifiques</strong> — touchant la <span class=\"kw-clinique\">neurocognition</span> et la <span class=\"kw-clinique\">cognition sociale</span></li>\n        <li><strong>Biais cognitifs</strong> — altérant l'<span class=\"kw-clinique\">interprétation des situations</span></li>\n      </ul>\n      <table >\n        <thead><tr><th>Critère</th><th>Handicap intellectuel</th><th>Handicap psychique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Origine</strong></td>\n            <td>Relié à un <span class=\"kw-etio\">déficit cognitif global</span> entraînant une <strong>déficience intellectuelle</strong></td>\n            <td>Secondaire à un <span class=\"kw-etio\">trouble psychiatrique</span> : déficits cognitifs spécifiques + biais cognitifs</td>\n          </tr>\n          <tr>\n            <td><strong>Apparition</strong></td>\n            <td><span class=\"kw-clinique\">Dès la naissance</span></td>\n            <td><span class=\"kw-clinique\">Adolescence</span>, <span class=\"kw-clinique\">âge adulte</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Évolution</span></strong></td>\n            <td><span class=\"kw-clinique\">Stable</span> — déficience <strong>durable</strong></td>\n            <td><span class=\"kw-alerte\">Évolutive</span></td>\n          </tr>\n          <tr>\n            <td><strong>Soins médicaux</strong></td>\n            <td>Habituellement <span class=\"kw-clinique\">peu fréquents</span> ; certains sont de nature à réduire le handicap</td>\n            <td><strong>Indispensables</strong>, d'intensité variable tout au long de la vie : stabiliser le trouble psychiatrique + réduire le handicap</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Tous <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">troubles psychiatriques sévères et persistants</span> sont susceptibles de conduire à une situation de handicap psychique.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 118 — Personne handicapé · 63 — Trouble schizophrénique · 64 — <span class=\"kw-etio\">Trouble bipolaire</span></em></p>","frequence":0},{"id":"121-2","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes généraux de la prise en charge","contenu":"<p>La prise en charge du handicap psychique s'organise selon le <span class=\"kw-def\">modèle de l'OMS</span> — une <strong>cascade en 3 niveaux</strong> qui va de l'atteinte initiale à ses conséquences sociales.</p>\n      <table >\n        <thead><tr><th>Niveau (modèle OMS)</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Déficiences</span></strong></td>\n            <td>Dynamiques cérébrales ; processus cognitifs ; <span class=\"kw-clinique\">symptômes psychiatriques</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Limitation d'activité</span></strong></td>\n            <td>Difficultés dans <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">tâches cognitives</span> plus ou moins complexes : mémoire ; attention ; planification ; prise de décision</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Restriction de participation</span></strong></td>\n            <td>Activités de la vie quotidienne ; adaptation aux lieux de vie ; <span class=\"kw-clinique\">habiletés sociales</span> ; soutien à l'emploi et aux ressources financières<br>→ <span class=\"kw-alerte\">isolement social</span> et perte d'autonomie</td>\n          </tr>\n        </tbody>\n      </table>\n      <p>L'offre de prise en charge se répartit en <strong>3 catégories de structures</strong> :</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Structures</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Structures médicales</strong></td>\n            <td>Hôpital de secteur ; <span class=\"kw-def\">CMP</span> (centre médico-psychologique) de secteur ; centre d'accueil de crise (24/24) ; hôpitaux de jour et <span class=\"kw-def\">CATTP</span> (centre d'accueil thérapeutique à temps partiel)</td>\n          </tr>\n          <tr>\n            <td><strong>Structures d'hébergement</strong></td>\n            <td>Foyers d'hébergement ; foyers de vie et <span class=\"kw-def\">FAM</span> (foyers d'accueil médicalisés) ; appartements thérapeutiques</td>\n          </tr>\n          <tr>\n            <td><strong>Structures socioprofessionnelles</strong></td>\n            <td>Entreprises adaptées (<span class=\"kw-chiffre\">80 %</span> des travailleurs handicapés) ; centres de distribution de travail à domicile ; <span class=\"kw-def\">ESAT</span> (établissement et service d'aide par le travail) ; foyer occupationnel ; services d'aide à la vie sociale</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> La prise en charge du handicap psychique est <strong>globale et graduée</strong> : elle combine <span class=\"kw-clinique\">soins médicaux</span>, <span class=\"kw-clinique\">hébergement adapté</span> et <span class=\"kw-clinique\">insertion professionnelle</span>, ajustés aux différents niveaux de dépendance et d'autonomie.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 119 — Soins et accompagnement dans la maladie chronique et le handicap · 62 — Offre de soin en psychiatrie</em></p>","frequence":0},{"id":"121-3","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes généraux de la prise en charge psychothérapeutique","contenu":"<p>La prise en charge des <strong>déficiences et des limitations d'activité</strong> repose sur plusieurs outils thérapeutiques, hiérarchisés par niveau de preuve.</p>\n      <table >\n        <thead><tr><th>Outil</th><th>Principe</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Éducation thérapeutique</span> (ETP)</strong></td>\n            <td>De la personne <strong>et surtout de sa famille</strong> — c'est l'outil avec le <span class=\"kw-alerte\">niveau de preuve le plus élevé</span></td>\n          </tr>\n          <tr>\n            <td><strong>Psychothérapies</strong></td>\n            <td>Visant à réduire le handicap : <span class=\"kw-clinique\">entraînement aux habiletés sociales</span> et autres techniques de <span class=\"kw-def\">TCC</span> (thérapies cognitivo-comportementales)</td>\n          </tr>\n          <tr>\n            <td><strong>Remédiation cognitive</strong></td>\n            <td>Entraînements spécifiques pour améliorer <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">fonctions cognitives déficientes</span></td>\n          </tr>\n          <tr>\n            <td><strong>Soins spécifiques</strong></td>\n            <td>Efficaces <strong>uniquement</strong> lorsqu'ils sont inclus dans une prise en charge <span class=\"kw-alerte\">globale</span> de la personne — à la fois sur le plan social et le plan médical</td>\n          </tr>\n        </tbody>\n      </table>\n      <p>La remédiation cognitive peut être complétée par des traitements :</p>\n      <ul>\n        <li><span class=\"kw-ttt\">Psychotropes</span> — médicaments régulant l'activité cérébrale, dont <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">effets secondaires</span> doivent être contrôlés</li>\n        <li><span class=\"kw-ttt\">Électroconvulsivothérapie</span> (ECT)</li>\n        <li><span class=\"kw-ttt\">Stimulation magnétique transcrânienne répétitive</span> (rTMS)</li>\n        <li><span class=\"kw-ttt\">Thérapies cognitivo-comportementales</span></li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Le plan médical n'a de sens qu'intégré au plan social : un <span class=\"kw-ttt\">traitement psychotrope</span> adapté stabilise le trouble, mais il ne réduit le handicap que s'il s'inscrit dans une prise en charge globale de la personne.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 73 — Techniques psychothérapeutiques · 74 — Psychotropes</em></p>","frequence":0},{"id":"121-4","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de la réhabilitation psychosociale","contenu":"<p>La <span class=\"kw-def\">réhabilitation psychosociale</span> regroupe <span class=\"kw-clinique\">les</span> différentes techniques permettant à la personne de <strong>développer des compétences</strong> pour faire face aux déficiences, limitations d'activité et restrictions de participation dont elle souffre. C'est l'<strong>axe global d'intervention</strong>, combinant <span class=\"kw-clinique\">remédiation cognitive</span> et <span class=\"kw-clinique\">réadaptation psychosociale</span>.</p>\n      <p>La prise en charge des <strong>restrictions de participation</strong> repose sur la réadaptation psychosociale : la <span class=\"kw-def\">MDPH</span> (via la <span class=\"kw-def\">CDAPH</span>) joue un rôle central en prenant des décisions sur <strong>3 domaines</strong>.</p>\n      <table >\n        <thead><tr><th>Domaine</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Logement</strong></td>\n            <td>\n              <strong>Vie autonome possible :</strong> logement ordinaire, adapté (maisons relais, résidences accueil) ou appartement communautaire / associatif ; accompagnement par <span class=\"kw-def\">SAVS</span> (service d'accompagnement à la vie sociale) ou <span class=\"kw-def\">SAMSAH</span> (qui assure en plus l'accompagnement du <span class=\"kw-def\">suivi</span> médical et paramédical) ; infirmiers à domicile ; aides ménagères ; soins médicaux ambulatoires<br>\n              <strong>Vie autonome impossible :</strong> structures d'hébergement pour adultes handicapés, accès ouvert par <span class=\"kw-alerte\">décision de la CDAPH</span> selon le niveau de dépendance — &lt;<span class=\"kw-chiffre\"> 60 ans</span> : foyers d'hébergement, foyers de vie / occupationnels, <span class=\"kw-def\">FAM</span>, <span class=\"kw-def\">MAS</span> (maisons d'accueil spécialisées) ; &gt;<span class=\"kw-chiffre\"> 60 ans</span> : résidences seniors / autonomie, MARPA, <span class=\"kw-def\">EHPAD</span>, <span class=\"kw-def\">USLD</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Travail / Aides financières</strong></td>\n            <td>\n              <strong>Milieu ordinaire possible :</strong> recherche d'emploi standard ; si <span class=\"kw-def\">RQTH</span> (reconnaissance de la qualité de travailleur handicapé) : aménagements du poste, formation en <span class=\"kw-def\">CRP</span> (centre de rééducation professionnelle)<br>\n              <strong>Milieu ordinaire impossible :</strong> la RQTH permet le travail en milieu protégé — entreprise adaptée ou <span class=\"kw-def\">ESAT</span><br>\n              <strong>Travail non possible :</strong> <span class=\"kw-alerte\">pension d'invalidité</span> (sécurité sociale) si le patient a déjà travaillé ; <span class=\"kw-alerte\">AAH</span> (allocation aux adultes handicapés, via la MDPH) s'il n'a pas suffisamment travaillé\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Vie sociale</strong></td>\n            <td>\n              <strong>Ergothérapie :</strong> ateliers animés par des professionnels (hôpitaux de jour du <span class=\"kw-def\">suivi</span> ambulatoire)<br>\n              <strong>GEM :</strong> groupes d'entraide mutuelle — associations loi 1901 indépendantes, luttant contre l'<span class=\"kw-alerte\">isolement</span> ; financement par l'<span class=\"kw-def\">ARS</span> ; développés par la loi handicap de <span class=\"kw-chiffre\">2005</span> ; <span class=\"kw-clinique\">les</span> personnes y prennent des responsabilités dans la définition des projets<br>\n              <strong>Pair-aidance :</strong> entraide entre personnes qui souffrent ou ont souffert d'une même maladie, fondée sur le partage de l'expérience vécue et du parcours de rétablissement\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège classique (annale).</strong>\n        <ul>\n          <li>Si le patient <strong>a déjà travaillé</strong> → on demande une <span class=\"kw-alerte\">pension d'invalidité</span>, <strong>pas une AAH</strong> (mais on peut demander la RQTH tout de même)</li>\n          <li>On <span class=\"kw-alerte\">n'accorde pas d'invalidité en phase aiguë</span> (ex. <span class=\"kw-clinique\">les</span> 6 premiers mois d'un <span class=\"kw-etio\">AVC</span>) : il faut attendre la <strong>consolidation des lésions</strong> pour se prononcer — en attendant, on fait un arrêt de travail</li>\n          <li>La <span class=\"kw-def\">RQTH</span> doit être demandée à la <strong>MDPH / CDAPH</strong> — pas au centre de formation professionnelle</li>\n        </ul>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 62 — Offre de soin en psychiatrie · 118 — Personne handicapé</em></p>","frequence":2},{"id":"121-5","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge judiciaire","contenu":"<p>La prise en charge judiciaire est envisagée lorsque le handicap nécessite que la personne soit <strong>conseillée ou contrôlée de manière continue</strong> dans <span class=\"kw-clinique\">les</span> actes de la vie civile — et parfois civique.</p>\n      <ul>\n        <li><strong>Démarche :</strong> des <span class=\"kw-clinique\">démarches judiciaires spécifiques</span> (auprès du <strong><span class=\"kw-def\">tribunal de grande instance</span></strong>) doivent être <span class=\"kw-alerte\">initiées par le médecin</span></li>\n        <li><strong>Objectif :</strong> mettre en place des <strong>mesures de protection des biens des majeurs</strong></li>\n      </ul>\n      <table >\n        <thead><tr><th>Mesure de protection</th><th>Principe</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Sauvegarde de justice</span></strong></td><td>Mesure de protection <span class=\"kw-clinique\">temporaire</span> et de mise en œuvre rapide</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Curatelle</span></strong></td><td>La personne est <span class=\"kw-clinique\">assistée ou conseillée</span> pour <span class=\"kw-clinique\">les</span> actes importants de la vie civile</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Tutelle</span></strong></td><td>La personne est <span class=\"kw-clinique\">représentée de manière continue</span> dans <span class=\"kw-clinique\">les</span> actes de la vie civile</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> <span class=\"kw-def\">Sauvegarde de justice</span>, curatelle et tutelle forment une <strong>gradation</strong> : c'est le médecin qui initie <span class=\"kw-clinique\">les</span> démarches auprès du tribunal, en fonction du degré de protection nécessaire.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 15 — Soins psychiatriques sans consentement</em></p>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>Handicap psychique :</strong> trouble <span class=\"kw-alerte\">évolutif</span> nécessitant des <span class=\"kw-ttt\">soins médicaux indispensables</span> tout au long de la vie — pas d'<span class=\"kw-alerte\">urgence</span> vitale propre.<br><strong>Crise psychiatrique :</strong> recours au <span class=\"kw-ttt\">centre d'accueil de crise (24/24)</span>, souvent rattaché aux <span class=\"kw-alerte\">urgences psychiatriques</span>.<br><strong>Piège invalidité :</strong> <span class=\"kw-ci\">on n'accorde pas d'invalidité en phase aiguë</span> — attendre la <span class=\"kw-chiffre\">consolidation des lésions</span> (ex. <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">6 premiers mois</span> d'un <span class=\"kw-alerte\">AVC</span>), sous couvert d'un <span class=\"kw-ttt\">arrêt de travail</span>.</p>","hospit":"<p><strong>Décideur :</strong> la <span class=\"kw-def\">MDPH</span> via la <span class=\"kw-def\">CDAPH</span> oriente selon le <span class=\"kw-chiffre\">niveau de dépendance</span> sur 3 domaines (logement, travail/aides, vie sociale).<br><strong>Structures médicales :</strong> <span class=\"kw-def\">hôpital de secteur</span>, <span class=\"kw-def\">CMP</span> de secteur (ambulatoire), <span class=\"kw-def\">hôpitaux de jour</span> et <span class=\"kw-def\">CATTP</span>.<br><strong>Hébergement :</strong> foyers d'hébergement, <span class=\"kw-def\">foyers de vie</span>/occupationnels, <span class=\"kw-def\">FAM</span>, <span class=\"kw-def\">MAS</span>, appartements thérapeutiques.<br><strong>Socioprofessionnel :</strong> <span class=\"kw-def\">entreprise adaptée</span>, <span class=\"kw-def\">ESAT</span>, accompagnement par <span class=\"kw-def\">SAVS</span>/<span class=\"kw-def\">SAMSAH</span>.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Trouble psychiatrique sévère et persistant</span> : toute pathologie psychiatrique sévère peut conduire à une situation de handicap</li><li><span class=\"kw-alerte\">Isolement social</span> majeur et perte d'autonomie dans la vie quotidienne</li><li><span class=\"kw-alerte\">Personne totalement dépendante</span> (raisons psychiques et/ou physiques) nécessitant une <span class=\"kw-def\">surveillance</span> médicale et des soins constants → <span class=\"kw-def\">MAS</span></li><li>Handicap nécessitant d'être <span class=\"kw-alerte\">conseillé ou contrôlé de manière continue</span> dans <span class=\"kw-clinique\">les</span> actes de la vie civile → <span class=\"kw-ttt\">mesure de protection juridique</span></li></ul>","principes":"<p><strong>Axe global :</strong> la <span class=\"kw-ttt\">réhabilitation psychosociale</span> = ensemble de techniques pour développer des compétences face aux <span class=\"kw-def\">déficiences</span>, <span class=\"kw-def\">limitations d'activité</span> et <span class=\"kw-def\">restrictions de participation</span> ; elle combine <span class=\"kw-ttt\">remédiation cognitive</span> et <span class=\"kw-ttt\">réadaptation psychosociale</span>.</p><p><strong>Déficiences & limitations d'activité</strong></p><p><span class=\"kw-clinique\">Les</span> soins spécifiques ne sont efficaces qu'inclus dans une prise en charge globale (plan social + plan médical)</p><ul><li><span class=\"kw-ttt\">Éducation thérapeutique</span> de la personne et surtout de sa <span class=\"kw-clinique\">famille</span> : <span class=\"kw-chiffre\">niveau de preuve le plus élevé</span></li><li><span class=\"kw-ttt\">Psychothérapies</span> visant à réduire le handicap : <span class=\"kw-ttt\">entraînement aux habiletés sociales</span> et autres techniques de <span class=\"kw-ttt\">TCC</span></li><li><span class=\"kw-ttt\">Remédiation cognitive</span> ; en <span class=\"kw-bio\">complément</span> possible : <span class=\"kw-ttt\">psychotropes</span>, <span class=\"kw-ttt\">ECT</span>, <span class=\"kw-ttt\">rTMS</span></li><li><span class=\"kw-ttt\">Traitement psychotrope</span> adapté, avec <span class=\"kw-clinique\">effets secondaires</span> contrôlés</li></ul><p><strong>Restrictions de participation (réadaptation psychosociale)</strong></p><p>Piège annale : si déjà travaillé → pension d'invalidité (pas l'AAH) ; la RQTH se demande à la MDPH/CDAPH</p><ul><li>Décisions de la <span class=\"kw-def\">MDPH</span>/<span class=\"kw-def\">CDAPH</span> sur 3 domaines : logement, travail ou aides financières, vie sociale</li><li><strong>Logement :</strong> ordinaire ou adapté (<span class=\"kw-def\">maisons relais</span>, <span class=\"kw-def\">résidences accueil</span>) + <span class=\"kw-def\">SAVS</span>/<span class=\"kw-def\">SAMSAH</span> si vie autonome ; sinon structures d'hébergement (foyers, <span class=\"kw-def\">FAM</span>, <span class=\"kw-def\">MAS</span>)</li><li><strong>Travail :</strong> milieu ordinaire avec <span class=\"kw-def\">RQTH</span> (aménagement du poste, formation en <span class=\"kw-def\">CRP</span>) ; ou milieu protégé (<span class=\"kw-def\">ESAT</span>, <span class=\"kw-def\">entreprise adaptée</span>)</li><li><strong>Aides si travail impossible :</strong> <span class=\"kw-ttt\">pension d'invalidité</span> (Sécurité sociale) si déjà travaillé, sinon <span class=\"kw-def\">AAH</span> (versée par la MDPH)</li><li><strong>Vie sociale :</strong> <span class=\"kw-ttt\">ergothérapie</span>, <span class=\"kw-def\">GEM</span> (Groupes d'Entraide Mutuelle, loi handicap <span class=\"kw-chiffre\">2005</span>), <span class=\"kw-def\">pair-aidance</span></li></ul><p><strong>PEC judiciaire</strong></p><ul><li>Indiquée si handicap nécessitant d'être <span class=\"kw-alerte\">conseillé ou contrôlé de manière continue</span> dans <span class=\"kw-clinique\">les</span> actes de la vie civile (voire civique)</li><li>Démarches judiciaires (<span class=\"kw-def\">tribunal de grande instance</span>) initiées par le <span class=\"kw-ttt\">médecin</span></li><li>Mesures de protection des majeurs : <span class=\"kw-ttt\">sauvegarde de justice</span>, <span class=\"kw-ttt\">tutelle</span>, <span class=\"kw-ttt\">curatelle</span></li></ul>","suivi":"<p><strong>Rythme :</strong> <span class=\"kw-ttt\">soins médicaux indispensables</span> d'<span class=\"kw-chiffre\">intensité variable tout au long de la vie</span>, visant à stabiliser le trouble et réduire le handicap.<br><strong><span class=\"kw-def\">Suivi</span> ambulatoire :</strong> <span class=\"kw-def\">CMP</span>, <span class=\"kw-def\">hôpitaux de jour</span> ; <span class=\"kw-ttt\">infirmiers à domicile</span> et <span class=\"kw-def\">SAMSAH</span> pour le suivi médical et paramédical.<br><strong>À surveiller :</strong> <span class=\"kw-clinique\">effets secondaires des psychotropes</span>, maintien dans le logement et l'emploi, lutte contre l'<span class=\"kw-alerte\">isolement social</span>.</p>"},"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Personne en situation de handicap psychique — Évaluation et orientation par la MDPH / CDAPH selon le niveau de dépendance","detail":"<h4>CAT — Orientation médico-sociale du handicap psychique — Décisions de la MDPH/CDAPH selon l'autonomie et la capacité de travail</h4>","branches":[{"to":"q-logement","label":"Volet logement & hébergement","color":"blue"},{"to":"q-travail","label":"Volet travail & ressources","color":"blue"}]},{"id":"q-logement","kind":"decision","label":"Vie autonome à l'extérieur possible ?","branches":[{"to":"t-domicile","label":"Oui","color":"green"},{"to":"q-age","label":"Non","color":"amber"}]},{"id":"t-domicile","kind":"terminal","label":"Maintien à domicile accompagné — Logement ordinaire ou adapté","color":"green","detail":"<h4>Conduite</h4><ul><li>Logement ordinaire, <span class=\"kw-def\">maisons relais</span>/<span class=\"kw-def\">résidences accueil</span> ou appartement communautaire</li><li>Accompagnement à la vie sociale : <span class=\"kw-def\">SAVS</span> ou <span class=\"kw-def\">SAMSAH</span> (<span class=\"kw-def\">suivi</span> médical/paramédical en plus)</li></ul><h4>Soins</h4><ul><li><span class=\"kw-ttt\">Soins médicaux ambulatoires</span> (visites à domicile) et <span class=\"kw-ttt\">infirmiers à domicile</span></li><li><span class=\"kw-ttt\">Aides ménagères</span> en <span class=\"kw-bio\">complément</span> si besoin</li></ul>"},{"id":"q-age","kind":"decision","label":"Adulte de moins de 60 ans ?","branches":[{"to":"t-hebergt-adulte","label":"Oui (< 60 ans)","color":"amber"},{"to":"t-ehpad","label":"Non (≥ 60 ans)","color":"amber"}]},{"id":"t-hebergt-adulte","kind":"terminal","label":"Hébergement pour adulte handicapé (< <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>60</span> ans</span>) — Accès ouvert par décision de la CDAPH selon la dépendance","color":"amber","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-def\">Foyer d'hébergement</span> : travailleurs handicapés en <span class=\"kw-def\">ESAT</span>/<span class=\"kw-def\">entreprise adaptée</span></li><li><span class=\"kw-def\">Foyer de vie</span>/occupationnel : ne pouvant pas travailler, sans soins</li><li><span class=\"kw-def\">FAM</span> : adulte très dépendant</li><li><span class=\"kw-def\">MAS</span> : <span class=\"kw-alerte\">totalement dépendant</span>, <span class=\"kw-def\">surveillance</span> médicale et soins constants</li></ul>"},{"id":"t-ehpad","kind":"terminal","label":"Hébergement personne âgée (≥ 60 ans) — Reste à charge plus important (APA possible)","color":"amber","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-def\">Résidence autonomie</span>/résidence senior, <span class=\"kw-def\">MARPA</span>, famille d'accueil agréée</li><li><span class=\"kw-def\">EHPAD</span> si personne âgée dépendante</li><li><span class=\"kw-def\">USLD</span> (unité de soins de longue durée)</li></ul>"},{"id":"q-travail","kind":"decision","label":"Travail en milieu ordinaire possible ?","branches":[{"to":"t-ordinaire","label":"Oui","color":"green"},{"to":"q-travail-protege","label":"Non","color":"amber"}]},{"id":"t-ordinaire","kind":"terminal","label":"Emploi en milieu ordinaire — Avec RQTH si besoin","color":"green","detail":"<h4>Conduite</h4><ul><li>Recherche d'un <span class=\"kw-def\">emploi standard</span></li><li>Si <span class=\"kw-def\">RQTH</span> (MDPH) : <span class=\"kw-ttt\">aménagement du poste de travail</span> + <span class=\"kw-ttt\">formation en CRP</span> (centre de rééducation professionnelle)</li></ul>"},{"id":"q-travail-protege","kind":"decision","label":"Travail en milieu protégé possible ?","branches":[{"to":"t-protege","label":"Oui","color":"amber"},{"to":"q-deja-travaille","label":"Non (travail impossible)","color":"amber"}]},{"id":"t-protege","kind":"terminal","label":"Travail en milieu protégé — Sous couvert de la RQTH","color":"amber","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-def\">Entreprise adaptée</span></li><li>ou <span class=\"kw-def\">ESAT</span> (parfois associé temporairement à un foyer d'hébergement)</li></ul>"},{"id":"q-deja-travaille","kind":"decision","label":"A déjà suffisamment travaillé / cotisé ?","branches":[{"to":"t-invalidite","label":"Oui (a déjà travaillé)","color":"amber"},{"to":"t-aah","label":"Non","color":"amber"}]},{"id":"t-invalidite","kind":"terminal","label":"Pension d'invalidité — Versée par la Sécurité sociale","color":"amber","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Pension d'invalidité</span> (Sécurité sociale) car le patient a déjà travaillé</li><li><span class=\"kw-ci\">Pas d'invalidité en phase aiguë</span> : attendre la <span class=\"kw-chiffre\">consolidation des lésions</span> (arrêt de travail en attendant)</li><li>La <span class=\"kw-def\">RQTH</span> peut être demandée en plus (à la MDPH/CDAPH)</li></ul>"},{"id":"t-aah","kind":"terminal","label":"AAH (allocation adulte handicapé) — Versée par la MDPH","color":"amber","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-def\">AAH</span> car le patient n'a pas suffisamment travaillé</li><li>Piège annale : si le patient avait déjà travaillé → <span class=\"kw-ttt\">pension d'invalidité</span>, pas l'AAH</li></ul>"}]},"cards":[{"i":"329f5c437cae","n":121,"o":"121-1","u":"Définition","t":"Connaître la définition du handicap psychique, connaître la différence avec le handicap intellectuel","q":"Quelle est la différence de prise en charge médicale entre le handicap intellectuel et le handicap psychique ?","a":"<ul><li>Pour le <strong>handicap intellectuel</strong>, les soins médicaux sont habituellement <strong>peu fréquents</strong>, bien que certains puissent réduire le handicap.</li><li>Pour le <strong>handicap psychique</strong>, les soins médicaux sont <strong>indispensables</strong>, d'intensité variable tout au long de la vie, visant à stabiliser le trouble psychiatrique et réduire le handicap.</li></ul>"},{"i":"691511aa3643","n":121,"o":"121-1","u":"Définition","t":"Connaître la définition du handicap psychique, connaître la différence avec le handicap intellectuel","q":"Combien de personnes sont estimées atteintes de handicap psychique en France et quelle est sa place selon l'OMS ?","a":"<p>On estime à <strong>700 000</strong> le nombre de personnes présentant un handicap psychique en France. Selon l'OMS, il fait partie des <strong>premières causes de handicap</strong>.</p>"},{"i":"6c07d3ae0755","n":121,"o":"121-1","u":"Définition","t":"Connaître la définition du handicap psychique, connaître la différence avec le handicap intellectuel","q":"Quelle est la différence d'étiologie entre le handicap intellectuel et le handicap psychique ?","a":"<ul><li>Le <strong>handicap intellectuel</strong> est relié à un <strong>déficit cognitif global</strong> entraînant une déficience intellectuelle.</li><li>Le <strong>handicap psychique</strong> est secondaire à un <strong>trouble psychiatrique</strong>, impliquant des déficits cognitifs spécifiques et des biais cognitifs.</li></ul>"},{"i":"ab8bacc8fd4f","n":121,"o":"121-1","u":"Définition","t":"Connaître la définition du handicap psychique, connaître la différence avec le handicap intellectuel","q":"Quelle est la différence d'apparition et d'évolution entre le handicap intellectuel et le handicap psychique ?","a":"<ul><li>Le <strong>handicap intellectuel</strong> apparaît généralement <strong>dès la naissance</strong> et son évolution est <strong>stable</strong> (déficience durable).</li><li>Le <strong>handicap psychique</strong> apparaît plutôt à l'<strong>adolescence ou à l'âge adulte</strong> et son évolution est <strong>évolutive</strong>.</li></ul>"},{"i":"c4038ecf5842","n":121,"o":"121-1","u":"Définition","t":"Connaître la définition du handicap psychique, connaître la différence avec le handicap intellectuel","q":"Quelle est la définition du handicap psychique ?","a":"<p>Le handicap psychique est une situation de handicap faisant suite à un <strong>trouble psychiatrique</strong>. Il se manifeste par des <strong>déficits cognitifs spécifiques</strong> (neurocognition et cognition sociale) et des <strong>biais cognitifs</strong> altérant l'interprétation des situations.</p>"}]};